import type { Camera } from "@babylonjs/lite";
import {
  getEffectiveAspectRatio,
  getViewMatrix,
  getViewProjectionMatrix,
  projectWorldToScreen,
  resolveCameraViewport,
} from "@babylonjs/lite";

export function labelPosition(...): {x,y,visible} {
  const backingWidth = canvas.width || canvas.clientWidth || 1;
  const backingHeight = canvas.height || canvas.clientHeight || 1;
  const cssWidth = canvas.clientWidth || canvas.getBoundingClientRect().width || backingWidth;
  const cssHeight = canvas.clientHeight || canvas.getBoundingClientRect().height || backingHeight;
  const viewport = resolveCameraViewport(camera, backingWidth, backingHeight);
  const aspect = getEffectiveAspectRatio(camera, backingWidth, backingHeight) || backingWidth / backingHeight;
  const view = getViewMatrix(camera);
  const viewProjection = getViewProjectionMatrix(camera, aspect);
  const result = projectWorldToScreen(point, view, viewProjection, { viewport, backingWidth, backingHeight, cssWidth, cssHeight });
  const x = Number.isFinite(result.cssX) ? result.cssX : 0;
  const y = Number.isFinite(result.cssY) ? result.cssY : 0;
  const front = !result.behindCamera && result.clipW > 0;
  const width = Math.max(0, cssWidth);
  const height = Math.max(0, cssHeight);
  const inside = width > 0 && height > 0 && Number.isFinite(x) && Number.isFinite(y) && x >= 0 && x <= width && y >= 0 && y <= height;
  const visible = front && inside;
  return { x, y, visible };
}
```

