import type { Camera } from "@babylonjs/lite";
import {
  getCameraPosition,
  getEffectiveAspectRatio,
  getViewMatrix,
  getViewProjectionMatrix,
  projectWorldToScreen,
  resolveCameraViewport,
} from "@babylonjs/lite";

function positiveNumber(...values: number[]): number {
  for (const value of values) {
    if (Number.isFinite(value) && value > 0) {
      return value;
    }
  }
  return 0;
}

function finiteNumber(value: number, fallback: number): number {
  return Number.isFinite(value) ? value : fallback;
}

export function labelPosition(camera: Camera, canvas: HTMLCanvasElement, point: { x: number; y: number; z: number }): { x: number; y: number; visible: boolean } {
  const rect = canvas.getBoundingClientRect();
  const cssWidth = positiveNumber(canvas.clientWidth, rect.width, canvas.width);
  const cssHeight = positiveNumber(canvas.clientHeight, rect.height, canvas.height);
  const backingWidth = positiveNumber(canvas.width, cssWidth);
  const backingHeight = positiveNumber(canvas.height, cssHeight);

  if (cssWidth === 0 || cssHeight === 0 || backingWidth === 0 || backingHeight === 0) {
    return { x: 0, y: 0, visible: false };
  }

  const viewport = resolveCameraViewport(camera, backingWidth, backingHeight);
  if (viewport.width <= 0 || viewport.height <= 0) {
    return { x: 0, y: 0, visible: false };
  }

  let aspect = getEffectiveAspectRatio(camera, backingWidth, backingHeight);
  if (!Number.isFinite(aspect) || aspect <= 0) {
    aspect = backingWidth / backingHeight;
  }

  const view = getViewMatrix(camera);
  const viewProjection = getViewProjectionMatrix(camera, aspect);

  const projectionOptions = {
    viewport,
    backingWidth,
    backingHeight,
    cssWidth,
    cssHeight,
    worldOrigin: camera._useFloatingOrigin ? getCameraPosition(camera) : undefined,
  };

  const projected = projectWorldToScreen(point, view, viewProjection, projectionOptions);

  const x = finiteNumber(projected.cssX, 0);
  const y = finiteNumber(projected.cssY, 0);

  const clipInFront = Number.isFinite(projected.clipW) ? projected.clipW > 0 : true;
  const finiteCss = Number.isFinite(projected.cssX) && Number.isFinite(projected.cssY);
  const visible = !projected.behindCamera && clipInFront && !projected.offscreen && finiteCss;

  return { x, y, visible };
}
